using System;using System.Collections.Generic;using Yarn.Unity;using UnityEngine;using System.Collections;using Unity.VisualScripting;public class TutorialManager : MonoBehaviour{    public static TutorialManager Instance;    private bool isAdvancingAfterAction = false;    private string currentShownPanelId = null;    public bool IsInputTutorialActive = false;    [Header("All Tutorial Sequences")]    public List<TutorialSequence> sequences = new List<TutorialSequence>();    private TutorialSequence activeSequence;    private int currentStepIndex = -1;        [Header("Brochure Puzzle")]    [SerializeField] private Vector2 Player1CameraRange;    [SerializeField] private Vector2 Player2CameraRange;    [SerializeField] private float inputFreezeTime = .5f;    private void Awake()    {        Instance = this;    }    [YarnCommand("StartTutorial")]    public void StartTutorial()    {        StartSequence("tutorial");    }    [YarnCommand("StartKeyTutorial")]      public void StartKeyTutorial()    {        StartSequence("keytutorial");        Debug.Log("Key tutorial started");        Cursor.lockState  = CursorLockMode.None;        Cursor.visible = true;    }    private void OnEnable()    {        PlayerEvents.OnMove         += HandleMove;        PlayerEvents.OnJump         += HandleJump;        PlayerEvents.OnInteract     += HandleInteract;        PlayerEvents.OnSubmit       += HandleSubmit;        PlayerEvents.OnResetCam     += HandleResetCam;        PlayerEvents.OnSwitchPlayer += HandleSwitchPlayer;        PlayerEvents.OnSlowMovement         += HandleSlow;        PlayerEvents.OnLook         += HandleLook;        PlayerEvents.OnRotate       += HandleRotate;        GameEvents.OnStartInputTutorial  +=HandleStartInputTutorial;        GameEvents.OnEndInputTutorial += TutorialPlayerMove;                //start: limit look (no up/down, limited angle)        //after match: can move + no look limit    }    private void Start()    {        //TODO: fix coroutine and switch this                /*StartCoroutine(PauseInput(5));*/        //TutorialPlayerLook();    }    private IEnumerator AdvanceAfterActionDelay(string hidePanelId, float waitSeconds, float fadeSeconds)    {        isAdvancingAfterAction = true;        yield return new WaitForSecondsRealtime(waitSeconds);        UIManager.Instance.HideUIWithFade(hidePanelId, fadeSeconds);        yield return new WaitForSecondsRealtime(fadeSeconds);        ShowNextStep();        isAdvancingAfterAction = false;    }    private void OnDisable()    {        PlayerEvents.OnMove -= HandleMove;        PlayerEvents.OnJump         -= HandleJump;        PlayerEvents.OnInteract     -= HandleInteract;        PlayerEvents.OnSubmit       -= HandleSubmit;        PlayerEvents.OnResetCam     -= HandleResetCam;        PlayerEvents.OnSwitchPlayer -= HandleSwitchPlayer;        PlayerEvents.OnSlowMovement        -= HandleSlow;        PlayerEvents.OnLook         -= HandleLook;        PlayerEvents.OnRotate       -= HandleRotate;                GameEvents.OnStartInputTutorial  -=HandleStartInputTutorial;        GameEvents.OnEndInputTutorial -= TutorialPlayerMove;    }    public void StartSequence(string sequenceId)    {        StopCoroutine("AdvanceAfterActionDelay");        isAdvancingAfterAction = false;        if (!string.IsNullOrEmpty(currentShownPanelId))        {            UIManager.Instance.HideUIWithFade(currentShownPanelId, 0.35f);            currentShownPanelId = null;        }        activeSequence = sequences.Find(s => s.sequenceId == sequenceId);        if (activeSequence == null)        {            Debug.LogError($"Tutorial sequence '{sequenceId}' not found!");            return;        }                currentStepIndex = -1;        ShowNextStep();    }        private void ShowNextStep()    {        currentStepIndex++;        if (activeSequence == null || currentStepIndex >= activeSequence.steps.Count)        {            Debug.Log("Tutorial sequence finished");            isAdvancingAfterAction = false;            currentShownPanelId = null;            activeSequence = null;            return;        }        var step = activeSequence.steps[currentStepIndex];        Debug.Log("Tutorial sequence finished2");        string inputType = PlayerInputManager.Instance.GetPlayer1InputType();        currentShownPanelId = step.panelId + (inputType == "Gamepad" ? "_Gamepad" : "_KBM");        UIManager.Instance.ShowUIWithFade(currentShownPanelId, 0.35f);    }        private void OnActionPerformed(PlayerAction action)    {        if (activeSequence == null)            return;                if (currentStepIndex < 0 || currentStepIndex >= activeSequence.steps.Count)            return;                var step = activeSequence.steps[currentStepIndex];                if (step.requiredAction != action)            return;        if (action == PlayerAction.SlowMovement)        {            string hideIdImmediate = !string.IsNullOrEmpty(currentShownPanelId)                ? currentShownPanelId                : step.panelId + ((PlayerInputManager.Instance.GetPlayer1InputType() == "Gamepad") ? "_Gamepad" : "_KBM");                        UIManager.Instance.HideUI(hideIdImmediate);            ShowNextStep();            return;        }                if (isAdvancingAfterAction)            return;        string hideId = !string.IsNullOrEmpty(currentShownPanelId)            ? currentShownPanelId            : step.panelId + ((PlayerInputManager.Instance.GetPlayer1InputType() == "Gamepad") ? "_Gamepad" : "_KBM");        StartCoroutine(AdvanceAfterActionDelay(hideId, 1f, 0.35f));    }        private void HandleMove()        => OnActionPerformed(PlayerAction.Move);    private void HandleJump()        => OnActionPerformed(PlayerAction.Jump);    private void HandleInteract()    => OnActionPerformed(PlayerAction.Interact);    private void HandleSubmit()      => OnActionPerformed(PlayerAction.Submit);    private void HandleResetCam()    => OnActionPerformed(PlayerAction.ResetCam);    private void HandleSwitchPlayer()=> OnActionPerformed(PlayerAction.SwitchPlayer);    private void HandleSlow()        => OnActionPerformed(PlayerAction.SlowMovement);    private void HandleLook()        => OnActionPerformed(PlayerAction.Look);    private void HandleRotate()      => OnActionPerformed(PlayerAction.Rotate);        public void HandleStartInputTutorial()    {        StartCoroutine(PauseInput(inputFreezeTime));    }    //pauses input before tutorial    private IEnumerator PauseInput(float seconds)    {        IsInputTutorialActive = true;        yield return new WaitForEndOfFrame();                PlayerInputManager.Instance.SetAllPlayersInputPaused(true);        PlayerInputManager.Instance.SaveInputData();        yield return new WaitForSeconds(seconds);                PlayerInputManager.Instance.SetAllPlayersInputPaused(false);        if(PlayerInputManager.Instance.CurrentControllerType == PlayerInputManager.ControllerType.SinglePlayer)         {PlayerInputManager.Instance.Player2.SetLookPaused(true);}        TutorialPlayerLook();        PlayerInputManager.Instance.SaveInputData();    }        public void TutorialPlayerLook()    {        PlayerInputManager.Instance.SetAllMovePaused(true);        PlayerInputManager.Instance.EnableTutorialLook(true, Player1CameraRange.x, Player1CameraRange.y, Player2CameraRange.x, Player2CameraRange.y);        PlayerInputManager.Instance.SaveInputData();    }    public void TutorialPlayerMove()    {//start: limit look (no up/down, limited angle)        //after match: can move + no look limitDebug.Log("function: tutorialplayermove");        IsInputTutorialActive = false;                if (PlayerInputManager.Instance.CurrentControllerType ==            PlayerInputManager.ControllerType.SinglePlayer)        {            PlayerInputManager.Instance.CurrPlayerObject.OldInputData.IsMovePaused = false;        }        else        {            PlayerInputManager.Instance.Player1.OldInputData.IsMovePaused = false;            PlayerInputManager.Instance.Player2.OldInputData.IsMovePaused = false;        }                PlayerInputManager.Instance.EnableTutorialLook(false, 0, 0, 0, 0);    }}